@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600&family=Source+Serif+4:opsz,wght@8..60,600&display=swap');
/* Amazon Toolkit · i4 Market Autopilot. Same family as the sheet: #4A1F3D header colour, brass accent, paper background. */
:root {
	--font-family: 'Inter', 'Segoe UI', Helvetica, Arial, sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 13px;
	--font-size-label: 14px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 24px;
	--font-size-paragraph: 14px;
	--font-size-link: 12px;
	--font-size-error: 12px;
	--font-size-html-h1: 26px;
	--font-size-html-h2: 20px;
	--font-size-html-h3: 16px;
	--font-size-html-h4: 14px;
	--font-size-html-h5: 12px;
	--font-size-html-h6: 11px;
	--font-size-subheader: 14px;

	/* Colors */
	--color-background: #f6eff4;
	--color-test-notice-text: #8a5a00;
	--color-test-notice-bg: #faf5ea;
	--color-test-notice-border: #e3d3ad;
	--color-card-bg: #ffffff;
	--color-card-border: #e2ddd5;
	--color-card-shadow: rgba(74,31,61, 0.10);
	--color-link: #4A1F3D;
	--color-header: #4A1F3D;
	--color-label: #2c3539;
	--color-input-border: #d6d0c6;
	--color-input-text: #1f2328;
	--color-focus-border: #4A1F3D;
	--color-submit-btn-bg: #4A1F3D;
	--color-submit-btn-text: #ffffff;
	--color-error: #DC143C;
	--color-required: #9C7A3C;
	--color-clear-button-bg: #8a8f98;
	--color-html-text: #2c3539;
	--color-html-link: #4A1F3D;
	--color-header-subtext: #5f6670;

	/* Border Radii */
	--border-radius-card: 4px;
	--border-radius-input: 3px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 4px;

	/* Spacing */
	--padding-container-top: 32px;
	--padding-card: 28px;
	--padding-test-notice-vertical: 12px;
	--padding-test-notice-horizontal: 24px;
	--margin-bottom-card: 16px;
	--padding-form-input: 12px;
	--card-padding: 28px;
	--card-margin-bottom: 16px;

	/* Dimensions */
	--container-width: 520px;
	--submit-btn-height: 46px;
	--checkbox-size: 18px;

	/* Others */
	--box-shadow-card: 0px 6px 20px 0px var(--color-card-shadow);
	--opacity-placeholder: 0.45;
}

/* Accents: a i4 colour bar on top of the card, brass rule under the title, serif title.
   If your n8n version names these parts differently, these lines are simply ignored. */
.card { border-top: 4px solid #4A1F3D; }
h1 { font-family: 'Source Serif 4', Georgia, serif; letter-spacing: 0.2px; }
h1::after { content: ''; display: block; width: 56px; height: 3px; background: #9C7A3C; margin: 12px auto 0; }
button[type='submit'], .submit-btn { letter-spacing: 0.4px; text-transform: none; }

parameters.jsCode:
// Autopilot step 1: read the form. One seed keyword, your product (optional), and a search budget (max 20).
const MAX_BUDGET = 20, MIN_BUDGET = 6; // 6 = 1 autocomplete + 1 page + 4 lookups, the smallest run that still says something
const form = $('Autopilot form').first().json;
const clean = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim().replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
const seed = clean(String(form['Seed keyword'] || '').split(/[\n,;]+/)[0]);
if (!seed || seed.replace(/[^a-z]/g, '').length < 3) throw new Error('No seed keyword entered. Type one product keyword, e.g. "neck pillow".');
const notes = [];
const num = (v, lo, hi, label) => {
  const raw = String(v ?? '').trim();
  if (raw === '') return null;
  const s = raw.replace(/[^0-9.]/g, '');
  const n = Number(s);
  if (s === '' || !Number.isFinite(n) || n < lo || n > hi) { notes.push(`"${label}" ignored: "${raw}"`); return null; }
  return n;
};
let budget = num(form['Search budget'], 1, 1000, 'Search budget') ?? MAX_BUDGET;
if (budget > MAX_BUDGET) { notes.push(`Search budget capped at ${MAX_BUDGET}`); budget = MAX_BUDGET; }
if (budget < MIN_BUDGET) { notes.push(`Search budget raised to ${MIN_BUDGET}, the smallest useful run`); budget = MIN_BUDGET; }
const ownRaw = String(form['Your brand or ASINs'] || '').split(/[\n,;]+/).map(s => s.trim()).filter(Boolean);
const isAsin = s => /^[A-Z0-9]{10}$/i.test(s) && /\d/.test(s);
return [{
  json: {
    batch_id: $now.toFormat('yyyy-MM-dd HH:mm:ss') + ' PKT',
    marketplace: form.Marketplace || 'amazon.com',
    seed,
    seeds: [seed],           // read by Collect Ideas (same code as i5)
    budget,
    you: {
      price: num(form['Your price'], 0.01, 100000, 'Your price'),
      rating: num(form['Your rating'], 1, 5, 'Your rating'),
      reviews: num(form['Your review count'], 0, 10000000, 'Your review count'),
    },
    own_asins: ownRaw.filter(isAsin).map(s => s.toUpperCase()),
    own_brands: ownRaw.filter(s => !isAsin(s)).map(s => s.toLowerCase().replace(/[^a-z0-9]/g, '')).filter(Boolean),
    notes,
  },
}];

// Collect keyword ideas from 3 Amazon sources, clean them, and mark which ones were already screened.
//   1. Amazon autocomplete for each seed (new searches)
//   2. "Related searches" Amazon showed under keywords you already searched (saved in the Keywords tab, free)
//   3. "Shopping ideas" filters Amazon showed (saved, free), joined to their keyword: "with handles" -> "resistance bands with handles"
// No AI. Brand-name ideas are set aside using brands seen on your saved pages, not a guess.
const MAX_PASTE = 10;
const plan = $('Plan Ideas').first().json;
const mk = plan.marketplace;
const lc = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const key = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const stem = w => w.replace(/(es|s)$/, '');
const LINK = new Set(['for', 'with', 'without', 'and', 'the', 'of', 'in', 'on', 'to', 'a']);
const words = s => lc(s).replace(/[^a-z0-9' ]/g, ' ').split(' ').filter(Boolean);
// Same words in any order = same search ("travel neck pillow" = "neck pillow travel")
const sameKey = s => words(s).filter(w => !LINK.has(w)).map(stem).sort().join(' ');
const headOf = kw => stem(lc(kw).split(/ (?:for|with|without|in|on|to|of|and) /)[0].split(' ').pop() || '');

// ---- Saved keyword rows (latest per keyword) ----
const kwRows = $('Read Keywords').all().map(i => i.json).filter(r => r.status === 'ok' && r.marketplace === mk && r.keyword);
const latest = {};
for (const r of kwRows) if (!latest[r.keyword] || String(r.checked_at) > String(latest[r.keyword].checked_at)) latest[r.keyword] = r;
const screened = {};
for (const r of Object.values(latest)) {
  const k = sameKey(r.keyword);
  if (!screened[k] || String(r.checked_at) > String(screened[k].checked_at)) screened[k] = r;
}

// Pages saved by any tool (i3 keeps a page without a Keywords row when it reused or before Oct 17): searched, but no score here
const pageSaved = {};
for (const l of $('Read History').all().map(i => i.json)) {
  if (l.marketplace !== mk || !l.keyword) continue;
  const k = sameKey(l.keyword);
  if (!pageSaved[k] || String(l.checked_at) > pageSaved[k]) pageSaved[k] = String(l.checked_at);
}

// ---- Brands seen on your pages (established: 1000+ reviews), minus words that are product words ----
const productWords = new Set(Object.keys(latest).concat(plan.seeds).flatMap(words).map(w => stem(key(w))));
const NOT_BRANDS = new Set(['black', 'white', 'grey', 'gray', 'blue', 'pink', 'red', 'green', 'ultra', 'royal', 'luxury', 'soft', 'memory', 'comfort', 'best', 'travel', 'portable', 'adjustable', 'premium', 'kids', 'heavy', 'large', 'small', 'extra', 'super', 'new', 'original', 'professional']);
// A real brand leads its titles ("JOOLA Ben Johns…"); a generic word ("fabric", "hanging", "anti") mostly sits mid-title.
// So a title-guessed brand counts only if, across all saved titles containing it, it is the first word at least 60% of the time.
const listings = $('Read History').all().map(i => i.json).filter(l => l.marketplace === mk && l.title);
const firstWord = {}, anyWord = {};
for (const l of listings) {
  const ws = words(l.title).map(key).filter(Boolean);
  if (ws[0]) firstWord[ws[0]] = (firstWord[ws[0]] || 0) + 1;
  for (const w of new Set(ws)) anyWord[w] = (anyWord[w] || 0) + 1;
}
const brands = new Set();
for (const l of listings) {
  if (Number(l.reviews || 0) < 1000) continue;
  const b = key(l.brand_guess);
  if (b.length < 3 || productWords.has(stem(b)) || NOT_BRANDS.has(b)) continue;
  if ((firstWord[b] || 0) / (anyWord[b] || 1) >= 0.6) brands.add(b);
}
for (const p of $('Read Products').all().map(i => i.json)) {
  const b = key(p.real_brand);
  if (p.marketplace === mk && b.length >= 3 && b !== 'notfound' && !productWords.has(stem(b))) brands.add(b);
}
const brandIn = s => {
  const ws = words(s).map(key);
  const joined = ws.join('');
  return [...brands].find(b => ws.includes(b) || (b.length >= 6 && joined.includes(b))) || null;
};

// ---- Which saved keywords feed this run ----
const seedHeads = new Set(plan.seeds.map(headOf));
const parents = Object.values(latest).filter(r => !plan.seeds.length || plan.seeds.includes(r.keyword) || seedHeads.has(headOf(r.keyword)));

// ---- Gather ----
const ideas = {};
const add = (text, source, parent, order) => {
  const t = lc(text);
  if (!t || t.length < 3) return;
  const k = sameKey(t);
  if (!k) return;
  const it = (ideas[k] ??= { idea: t, variants: new Set(), sources: new Set(), parents: new Set(), first_order: 999 });
  if (t !== it.idea) it.variants.add(t);
  it.sources.add(source);
  it.parents.add(parent);
  it.first_order = Math.min(it.first_order, order);
};
let acFailed = [];
let acCount = 0;
try {
  if ($('Amazon Autocomplete (SerpApi)').isExecuted) {
    const res = $('Amazon Autocomplete (SerpApi)').all().map(i => i.json);
    plan.seeds.forEach((seed, i) => {
      const r = res[i] || {};
      if (r.error || !Array.isArray(r.suggestions)) { acFailed.push(seed); return; }
      r.suggestions.filter(s => !s.type || s.type === 'KEYWORD').forEach((s, j) => { acCount++; add(s.value, 'autocomplete', seed, j); });
    });
  }
} catch (e) { /* no seeds, autocomplete did not run */ }
for (const r of parents) {
  String(r.related_searches || '').split(' | ').forEach((s, j) => add(s, 'related searches', r.keyword, 20 + j));
  String(r.shopping_ideas || '').split(' | ').filter(Boolean).forEach((m, j) => {
    const mod = lc(m);
    if (!mod) return;
    const phrase = /^(with|for|without)\b/.test(mod) ? `${r.keyword} ${mod}` : `${mod} ${r.keyword}`;
    add(phrase, 'shopping filter', r.keyword, 40 + j);
  });
}

// ---- Judge each idea ----
const inputKeys = new Set([...plan.seeds, ...parents.map(p => p.keyword)].map(sameKey));
const heads = new Set([...seedHeads, ...parents.map(p => headOf(p.keyword))]);
const SRC_ORDER = ['autocomplete', 'related searches', 'shopping filter'];
let rows = Object.entries(ideas).filter(([k]) => !inputKeys.has(k)).map(([k, it]) => {
  const brand = brandIn(it.idea);
  const related = words(it.idea).map(stem).some(w => heads.has(w));
  const s = screened[k];
  return {
    idea: it.idea,
    group: brand ? 'brand name' : related ? 'same product' : 'nearby market',
    brand_found: brand || '',
    sources: SRC_ORDER.filter(x => it.sources.has(x)).join(' + '),
    source_count: it.sources.size,
    suggested_under: [...it.parents].join(' | '),
    mentions: it.parents.size,
    status: s ? 'screened' : pageSaved[k] ? 'page saved, not scored' : 'new',
    last_score: s ? s.opportunity_score : '',
    last_confidence: s ? s.confidence : '',
    last_checked: s ? s.checked_at : (pageSaved[k] || ''),
    same_as: [...it.variants].join(' | '),
    _order: it.first_order,
  };
});
// Order: same product first, then nearby markets, brands last; within a group: more sources, more mentions, Amazon's own order
const G = { 'same product': 0, 'nearby market': 1, 'brand name': 2 };
rows.sort((a, b) => (G[a.group] - G[b.group]) || (b.source_count - a.source_count) || (b.mentions - a.mentions) || (a._order - b._order) || a.idea.localeCompare(b.idea));
const total = rows.length;
const groups = { same_product: rows.filter(r => r.group === 'same product').length, nearby_market: rows.filter(r => r.group === 'nearby market').length, brand_name: rows.filter(r => r.group === 'brand name').length };
// Listed: up to 60 same-product, 25 nearby-market and 15 brand-name ideas, so every group stays visible
const CAP = { 'same product': 60, 'nearby market': 25, 'brand name': 15 };
const seen = {};
rows = rows.filter(r => (seen[r.group] = (seen[r.group] || 0) + 1) <= CAP[r.group]).map(({ _order, ...r }, i) => ({ rank: i + 1, ...r }));

const paste = rows.filter(r => r.group === 'same product' && r.status === 'new').slice(0, MAX_PASTE).map(r => r.idea);
const notes = [...plan.notes];
if (acFailed.length) notes.push(`Autocomplete failed for: ${acFailed.join(', ')}`);
if (plan.seeds.length && !parents.length) notes.push('None of your saved keywords match these seeds yet, so saved suggestions add nothing; run them through i1 to collect more');
if (total > rows.length) notes.push(`${total} ideas found; the top ${rows.length} are listed (up to 60 same-product, 25 nearby-market, 15 brand-name)`);
return [{
  json: {
    rows,
    total,
    groups,
    paste,
    parents_used: parents.map(p => p.keyword),
    autocomplete_suggestions: acCount,
    searches_used: plan.seeds.length,
    notes,
  },
}];

// Autopilot step 3: choose what to screen. The seed + the top 5 same-product ideas, each page reused if saved in the last 24 h.
// Budget: 1 search already went to autocomplete; at least 4 are kept for product lookups; pages get the rest.
const MAX_IDEAS = 5, REUSE_HOURS = 24, KEEP_FOR_LOOKUPS = 4;
const p = $('Plan Ideas').first().json;
// Pakistan-time stamps written by the tools come back from Google Sheets as a date: "2026-10-17 5:53:17" (no leading zero),
// or as a serial number. Read all of them; anything unreadable counts as "too old" (never reused by mistake).
const pkMs = v => {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round((v - 25569) * 86400000) - 5 * 3600000;
  const m = String(v ?? '').match(/(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  return m ? Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +(m[6] || 0)) - 5 * 3600000 : NaN;
};
const hoursAgo = v => (Date.now() - pkMs(v)) / 3600000;
const recent = v => { const h = hoursAgo(v); return Number.isFinite(h) && h >= -0.1 && h <= REUSE_HOURS; };
const ideas = $('Collect Ideas').first().json.rows.filter(r => r.group === 'same product').map(r => r.idea);
const toMs = t => Date.parse(String(t).replace(' UTC', 'Z').replace(' ', 'T'));
// Same words in any order = same search (same rule as i5): "neck pillow travel" can reuse the saved "neck pillow for travel" page
const LINK = new Set(['for', 'with', 'without', 'and', 'the', 'of', 'in', 'on', 'to', 'a']);
const sameKey = t => String(t).toLowerCase().replace(/[^a-z0-9' ]/g, ' ').split(' ').filter(w => w && !LINK.has(w)).map(w => w.replace(/(es|s)$/, '')).sort().join(' ');
const fresh = {};
for (const r of $('Read History').all().map(i => i.json)) {
  if (!r.run_id || r.marketplace !== p.marketplace || !r.keyword) continue;
  const t = toMs(r.checked_at), k = sameKey(r.keyword);
  if ((Date.now() - t) / 3600000 > REUSE_HOURS || t > Date.now() + 60000) continue;
  if (!fresh[k] || t > fresh[k].t) fresh[k] = { keyword: r.keyword, run_id: r.run_id, t };
}
// A keyword that failed in the last 24 h (e.g. too few matching listings) would fail again: skip it, don't pay twice
const failedRecently = new Set($('Read Keywords').all().map(i => i.json)
  .filter(r => r.status === 'failed' && r.marketplace === p.marketplace && r.keyword && recent(r.batch_id))
  .map(r => sameKey(r.keyword)));
// Candidates: the seed, then up to 5 ideas. Ideas with a page saved in the last 24 h go first (free), so a repeat run
// screens the same markets as the first one instead of paying for new ones; new ideas fill the remaining slots.
const skipped = [];
const seen = new Set();
const asCandidate = idea => { const f = fresh[sameKey(idea)]; return f ? f.keyword : idea; };
const seedKw = asCandidate(p.seed);
seen.add(sameKey(seedKw));
const pool = [];
for (const idea of ideas) {
  const k = sameKey(idea);
  if (seen.has(k)) continue;
  seen.add(k);
  if (failedRecently.has(k)) { skipped.push(`${idea} (failed in the last 24 h)`); continue; }
  pool.push(asCandidate(idea));
}
const saved = pool.filter(kw => fresh[sameKey(kw)]), unsaved = pool.filter(kw => !fresh[sameKey(kw)]);
let candidates = [seedKw, ...[...saved, ...unsaved].slice(0, MAX_IDEAS)];
// Repeat of the same seed within 24 h: screen exactly the markets the earlier run screened, so the report is comparable
const prev = $('Read Autopilot Runs').all().map(i => i.json)
  .filter(r => r.seed === p.seed && r.marketplace === p.marketplace && r.pages && recent(r.checked_at))
  .sort((a, b) => pkMs(b.checked_at) - pkMs(a.checked_at))[0];
const repeatNote = [];
if (prev) {
  const prevKws = String(prev.pages).split(' | ').map(x => x.replace(/: (reused|new search)$/, '')).filter(Boolean);
  candidates = prevKws.filter(kw => kw === seedKw || !failedRecently.has(sameKey(kw)));
  repeatNote.push(`Repeat of the ${prev.checked_at} run: same ${candidates.length} keywords screened`);
}
const latest = Object.fromEntries(candidates.filter(kw => fresh[sameKey(kw)]).map(kw => [kw, fresh[sameKey(kw)]]));
const used = 1; // the autocomplete search
let pageRoom = Math.max(0, p.budget - used - KEEP_FOR_LOOKUPS);
const notes = [...p.notes, ...repeatNote];
const pages = [];
for (const keyword of candidates) {
  const l = latest[keyword];
  const age = l ? (Date.now() - l.t) / 3600000 : null;
  const reuse = !!l;
  if (!reuse && pageRoom === 0) { skipped.push(keyword); continue; }
  if (!reuse) pageRoom--;
  pages.push({ order: pages.length + 1, keyword, marketplace: p.marketplace, reuse, reuse_run_id: reuse ? l.run_id : null, age_hours: age === null ? null : Math.round(age * 10) / 10 });
}
if (skipped.length) notes.push(`Not screened: ${skipped.map(k => (k.includes('(failed') ? k : `${k} (search budget)`)).join(', ')}`);
const searched = pages.filter(x => !x.reuse).length;
return [{
  json: {
    batch_id: p.batch_id, marketplace: p.marketplace, keywords: pages.map(x => x.keyword), pages,
    to_search: pages.filter(x => !x.reuse).map(x => x.keyword), any_search: searched > 0,
    skipped, used_after_pages: used + searched, notes,
  },
}];

// One item per keyword that needs a new Amazon search (1 SerpApi search each)
const plan = $('Plan Screen').first().json;
return plan.pages.filter(p => !p.reuse).map(p => ({ json: { keyword: p.keyword, marketplace: p.marketplace, order: p.order } }));

// Bundle what the core needs: fresh searches + saved runs, plus the history for the stability check.
// Search results line up with Split Searches by position (failed searches included, the core reports them).
const plan = $('Plan Screen').first().json;
let fresh = [];
try {
  if ($('Search Amazon (SerpApi)').isExecuted) fresh = $('Search Amazon (SerpApi)').all().map(i => i.json);
} catch (e) {
  fresh = []; // every page was reused, the search node did not run
}
const searched = plan.pages.filter(p => !p.reuse);
const history = $('Read History').all().map(i => i.json).filter(r => r.run_id);
const searches = plan.pages.map(p => {
  const s = { order: p.order, keyword: p.keyword, marketplace: p.marketplace };
  if (p.reuse) s.listings = history.filter(r => r.run_id === p.reuse_run_id);
  else s.response = fresh[searched.indexOf(p)] ?? { error: 'no response' };
  return s;
});
return [{ json: { tool: 'i4', batch_id: plan.batch_id, searches, history, dropped: [] } }];

// Keyword rows for NEW searches only (score, stats, Amazon's related searches), so i5 and later reuse runs can read them.
// Reused pages already have their Keywords row from the tool that searched them.
const plan = $('Plan Screen').first().json;
return $('Toolkit Core').first().json.keywords
  .filter(k => plan.to_search.includes(k.keyword))
  .map(json => ({ json }));

// Market rows only when this run searched something new (a fully reused run adds nothing new to the Markets tab)
const plan = $('Plan Screen').first().json;
if (!plan.any_search) return [];
return $('Toolkit Core').first().json.markets.map(json => ({ json }));

// Autopilot step 5: pick the winning market with i1's own ranking. Ties (gap under run-to-run noise) go to the higher confidence.
// Output has the same shape as i3's "Plan Run", so i3's Rank / Judge code runs on the winner unchanged.
const p = $('Plan Ideas').first().json;
const s = $('Plan Screen').first().json;
const core = $('Toolkit Core').first().json;
const markets = [...(core.markets || [])].sort((a, b) => a.rank - b.rank);
if (!markets.length) throw new Error(`None of the screened keywords could be analyzed (${s.keywords.join(', ')}). See the core notes.`);
// Markets tied with #1: walk down while each says "treat these two as tied"
const noiseOf = m => Number((String(m.vs_next || '').match(/up to (\d+) points/) || [])[1] || 0);
const tied = [markets[0]];
for (let i = 0; i < markets.length - 1 && /tied/.test(markets[i].vs_next || ''); i++) {
  if (markets[0].opportunity_score - markets[i + 1].opportunity_score >= noiseOf(markets[i])) break;
  tied.push(markets[i + 1]);
}
const CONF = { high: 3, medium: 2, low: 1 };
const winner = [...tied].sort((a, b) => (CONF[b.confidence] || 0) - (CONF[a.confidence] || 0) || b.opportunity_score - a.opportunity_score)[0];
const why = tied.length > 1
  ? `Tied on score with ${tied.filter(m => m !== winner).map(m => `"${m.market}" (${m.opportunity_score}, ${m.confidence})`).join(', ')}; picked for ${tied.every(m => m.confidence === winner.confidence) ? `the higher score (same ${winner.confidence} confidence)` : `${winner.confidence} confidence`}`
  : markets.length > 1 ? `Clear #1: ${winner.vs_next}` : 'Only market that could be analyzed';
const winKeywords = String(winner.keywords).split(', ').filter(Boolean);
return [{
  json: {
    batch_id: p.batch_id,
    marketplace: p.marketplace,
    keywords: winKeywords,
    pages: s.pages.filter(x => winKeywords.includes(x.keyword)),
    to_search: [],
    you: p.you,
    own_asins: p.own_asins,
    own_brands: p.own_brands,
    notes: s.notes,
    lookup_budget: Math.max(0, p.budget - s.used_after_pages),
    winner: winner.market,
    winner_score: winner.opportunity_score,
    winner_confidence: winner.confidence,
    why_winner: why,
    tied_with: tied.filter(m => m !== winner).map(m => m.market),
  },
}];

// Merge the keyword pages into ONE competitor list and rank it by relevance. No AI: every number comes from the pages.
// A competitor = product families (variations grouped by the core) from different keywords that are the same product:
//   they share an ASIN, or they have the same brand + same shared review count (50+) + same rating (the core's family rule).
const MAX_LISTED = 25;   // rows written to the Targets tab
const plan = $('Plan Run').first().json;
const MAX_LOOKUPS = Math.min(8, plan.lookup_budget ?? 8); // product-page lookups (1 SerpApi search each); Autopilot passes a smaller budget
const REUSE_HOURS = 24;  // a Products row this fresh is reused instead of a new lookup
const core = $('Toolkit Core').first().json;
// Only the pages of this run's keywords (Autopilot screens more keywords than it targets)
const details = (core.details || []).filter(d => plan.keywords.includes(d.keyword));
if (!details.length) throw new Error('None of the keywords could be analyzed. See the Keywords notes in the core output.');
const r1 = x => Math.round(x * 10) / 10;
const clamp = x => Math.max(0, Math.min(1, x));
const bkey = b => String(b || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const k = details.length;
const stem = w => w.replace(/(es|s)$/, '');
// Title first-words that are colours or adjectives, not brands (seen live: "Black", "Ultra", "Royal")
const NOT_BRANDS = new Set(['black', 'white', 'grey', 'gray', 'blue', 'pink', 'red', 'green', 'purple', 'beige', 'navy', 'ultra', 'royal', 'luxury', 'soft', 'memory', 'comfort', 'best', 'travel', 'portable', 'adjustable', 'deluxe', 'classic', 'organic', 'natural']);
const kwWords = new Set(plan.keywords.flatMap(kw => kw.split(' ')).map(w => stem(bkey(w))));

// ---- 1. Every family on every page, with its page's total sales ----
const nodes = [];
details.forEach((d, ki) => {
  const pageUnits = (d.families || []).reduce((s, f) => s + (f.units || 0), 0);
  for (const f of d.families || []) nodes.push({ ki, keyword: d.keyword, run_id: d.run_id, pageUnits, f, bk: bkey(f.brand) });
});

// ---- 2. Union families that are the same product across pages ----
const parent = nodes.map((_, i) => i);
const find = i => (parent[i] === i ? i : (parent[i] = find(parent[i])));
const join = (a, b) => { parent[find(a)] = find(b); };
const byAsin = {};
nodes.forEach((n, i) => { for (const a of n.f.asins) { if (byAsin[a] !== undefined) join(i, byAsin[a]); else byAsin[a] = i; } });
const sig = {};
nodes.forEach((n, i) => {
  if ((n.f.reviews || 0) < 50 || n.f.rating === null || !n.bk) return;
  const s = `${n.bk}|${n.f.reviews}|${n.f.rating}`;
  if (sig[s] !== undefined) join(i, sig[s]); else sig[s] = i;
});
const groups = {};
nodes.forEach((n, i) => (groups[find(i)] ??= []).push(n));

// Brands with an established (1000+ review) product on any page: their low-review listings are not newcomers
const established = new Set(nodes.filter(n => n.f.reviews >= 1000 && n.bk).map(n => n.bk));

// ---- 3. One record per competitor ----
let competitors = Object.values(groups).map(members => {
  const byKw = {};
  for (const m of members) { // a product can appear twice on one page only as two families; keep the bigger one
    const cur = byKw[m.keyword];
    if (!cur || m.f.units > cur.f.units || (m.f.units === cur.f.units && m.f.position < cur.f.position)) byKw[m.keyword] = m;
  }
  const per = Object.values(byKw);
  const lead = [...per].sort((a, b) => (b.f.units - a.f.units) || (a.f.position - b.f.position))[0];
  const mostReviews = [...per].sort((a, b) => b.f.reviews - a.f.reviews)[0];
  const asins = [...new Set(members.flatMap(m => m.f.asins))];
  const best_position = Math.min(...per.map(m => m.f.position));
  // Sales: the HIGHEST badge floor across keywords, never the sum (the same buyers show up on every page)
  const units = Math.max(...per.map(m => m.f.units || 0));
  const shares = per.map(m => (m.pageUnits ? m.f.units / m.pageUnits : 0));
  const share = Math.max(...shares);
  // A "brand" that is just a word from your keywords (e.g. "Resistance") is a title guess gone wrong: treat as unknown
  const guessed = (per.find(m => m.f.brand) || {}).f?.brand || null;
  const brand = guessed && (kwWords.has(stem(bkey(guessed))) || NOT_BRANDS.has(bkey(guessed))) ? null : guessed;
  const coverageN = per.length;
  const pCov = 50 * coverageN / k;
  const pPos = 30 * clamp(1 - (best_position - 1) / 50);
  const pShare = 20 * clamp(share / 0.2);
  const relevance = Math.round(pCov + pPos + pShare);
  return {
    competitor_asin: lead.f.best_asin,
    asins,
    family_id: lead.f.family_id,
    brand,
    brand_key: bkey(brand),
    title: lead.f.title,
    keywords_ranked_on: per.sort((a, b) => a.ki - b.ki).map(m => `${m.keyword} (#${m.f.position})`).join(' | '),
    coverage: `${coverageN} of ${k}`,
    coverage_n: coverageN,
    best_position,
    lead_keyword: lead.keyword,
    lead_run_id: lead.run_id,
    has_sales: per.some(m => m.f.has_sales),
    units_floor: units,
    page_sales_share_pct: r1(share * 100),
    price: lead.f.price,
    rating: mostReviews.f.rating,
    reviews: mostReviews.f.reviews,
    family_size: lead.f.asins.length,
    newcomer: mostReviews.f.reviews < 1000 && !established.has(bkey(brand)),
    relevance,
    relevance_breakdown: `keywords ${coverageN}/${k} → ${r1(pCov)}/50 + best position #${best_position} → ${r1(pPos)}/30 + page sales share ${r1(share * 100)}% → ${r1(pShare)}/20 (full at 20%)`,
  };
});

// ---- 4. Leave out your own products ----
// Exact brand match only: "Napfun Pro" must not hide "Napfun"
const isOwn = c => c.asins.some(a => plan.own_asins.includes(a))
  || (c.brand_key && plan.own_brands.includes(c.brand_key));
const ownCount = competitors.filter(isOwn).length;
competitors = competitors.filter(c => !isOwn(c));

// Fixed order: relevance, then sales, then reviews, then position (same data always gives the same list)
competitors.sort((a, b) => (b.relevance - a.relevance) || (b.units_floor - a.units_floor) || (b.reviews - a.reviews) || (a.best_position - b.best_position));

// ---- 5. Market medians: the comparison point when you did not enter your own product ----
const median = arr => {
  const v = arr.filter(x => typeof x === 'number' && Number.isFinite(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = Math.floor(v.length / 2);
  return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
};
const selling = competitors.filter(c => c.units_floor > 0);
const base = selling.length >= 5 ? selling : competitors;
const market = {
  price: median(base.map(c => c.price)) === null ? null : Math.round(median(base.map(c => c.price)) * 100) / 100,
  rating: median(base.map(c => c.rating)),
  reviews: median(base.map(c => c.reviews)),
  based_on: `${base.length} ${base === selling ? 'selling ' : ''}competitors`,
};

// ---- 6. Which products get a product-page lookup (BSR, seller, real brand, 1-2 star share) ----
const listed = competitors.slice(0, MAX_LISTED).map((c, i) => ({ ...c, rank: i + 1 }));
const toMs = t => Date.parse(String(t).replace(' UTC', 'Z').replace(' ', 'T'));
const runTime = runId => toMs(String(runId || '').split('|').pop());
const now = Date.now();
const saved = $('Read Products').all().map(i => i.json)
  .filter(p => p.asin && p.lookup_status === 'ok' && p.marketplace === plan.marketplace)
  .map(p => ({ ...p, age_hours: (now - runTime(p.run_id)) / 3600000 }))
  .filter(p => Number.isFinite(p.age_hours) && p.age_hours >= 0 && p.age_hours <= REUSE_HOURS)
  .sort((a, b) => a.age_hours - b.age_hours);
const reused = {};
const lookups = [];
for (const c of listed.slice(0, MAX_LOOKUPS)) {
  const hit = saved.find(p => c.asins.includes(p.asin));
  if (hit) { reused[c.competitor_asin] = hit; continue; }
  lookups.push({
    role: `i3 target #${c.rank}`, asin: c.competitor_asin, family_id: c.family_id, family_size: c.family_size,
    brand_guess: c.brand ?? '', title: c.title, price: c.price, rating: c.rating, reviews: c.reviews,
    units_family: c.units_floor, keyword: c.lead_keyword, marketplace: plan.marketplace, run_id: c.lead_run_id,
  });
}

// ---- 7. Keyword ideas from Amazon's own suggestions (saved by every search, so 0 extra searches) ----
const latestKw = {};
const kwRows = [...$('Read Keywords').all().map(i => i.json), ...(core.keywords || [])]
  .filter(r => r.status === 'ok' && r.marketplace === plan.marketplace && plan.keywords.includes(r.keyword));
for (const r of kwRows) if (!latestKw[r.keyword] || String(r.checked_at) > String(latestKw[r.keyword].checked_at)) latestKw[r.keyword] = r;
// Head word = the product noun: last word before "for/with/..." ("neck pillow for travel" -> pillow, not travel)
const headOf = kw => kw.split(/ (?:for|with|without|in|on|to|of|and) /)[0].split(' ').pop();
const heads = new Set(plan.keywords.map(kw => stem(headOf(kw))));
const suggestions = new Set();
for (const r of Object.values(latestKw)) for (const s of String(r.related_searches || '').split(' | ')) {
  const t = s.toLowerCase().trim();
  if (t && !plan.keywords.includes(t)) suggestions.add(t);
}
const related = [], complements = [];
for (const s of suggestions) (s.split(' ').some(w => heads.has(stem(w))) ? related : complements).push(s);

// Keywords that could not be analyzed
const failed = (core.keywords || []).filter(r => r.status !== 'ok' && plan.keywords.includes(r.keyword)).map(r => `${r.keyword} (${r.status}: ${r.note || ''})`);

return [{
  json: {
    listed,
    competitors_found: competitors.length + ownCount,
    own_excluded: ownCount,
    market,
    lookups,
    any_lookup: lookups.length > 0,
    reused,
    pages: details.map(d => ({ keyword: d.keyword, run_id: d.run_id, reused: d.reused, families: (d.families || []).length })),
    keywords_ok: k,
    failed,
    related_keywords: related.slice(0, 10),
    complement_ideas: complements.slice(0, 10),
  },
}];

// Turn each product-page lookup into one row of facts. Anything the page does not show is "not found", never 0.
// Lookups line up with Split Lookups by position; a failed lookup keeps the pick and says why.
const picks = $('Split Lookups').all().map(i => i.json);
const pages = $('Look Up Product (SerpApi)').all().map(i => i.json);
const NF = 'not found';

// Find the first value stored under `key` anywhere inside an object (offer layouts differ between products)
function findKey(obj, key, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 6) return undefined;
  if (key in obj) return obj[key];
  for (const v of Object.values(obj)) {
    const hit = findKey(v, key, depth + 1);
    if (hit !== undefined) return hit;
  }
  return undefined;
}
const text = v => (v === undefined || v === null || v === '' ? null : typeof v === 'object' ? (v.text ?? v.content ?? null) : String(v));
function errorText(res) {
  const e = res?.error;
  if (!e) return null;
  let msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  const m = String(msg).match(/\\?"error\\?"\s*:\s*\\?"(.+?)\\?"/);
  return String(m ? m[1] : msg).replace(/\s+/g, ' ').trim().slice(0, 200);
}

return picks.map((p, idx) => {
  const page = pages[idx] || {};
  const base = {
    row_id: `i4|${p.run_id}|${p.asin}`, run_id: p.run_id, keyword: p.keyword, marketplace: p.marketplace,
    role: p.role, asin: p.asin, family_id: p.family_id, family_listings_on_page: p.family_size,
    title: p.title, brand_guess: p.brand_guess, price: p.price, rating: p.rating, reviews: p.reviews,
    units_family_on_page: p.units_family,
  };
  const err = errorText(page);
  const pr = page.product_results;
  if (err || !pr) {
    return { json: { ...base, lookup_status: 'failed', lookup_note: err || 'no product data returned', real_brand: NF, brand_guess_correct: 'unknown', sold_by: NF, ships_from: NF, fulfilled_by_amazon: NF, bsr_category: NF, bsr_all: NF, variations: NF, bought_last_month_page: NF, review_summary: NF, one_two_star_pct: NF, themes: [] } };
  }
  const pd = page.product_details || {};
  const spec = page.item_specifications || {};
  const realBrand = text(pd.brand_name) || text(spec.brand)
    || (pr.brand ? String(pr.brand).replace(/^Brand:\s*/i, '').replace(/^Visit the (.+) Store$/i, '$1').trim() : null);
  const soldBy = text(findKey(page.purchase_options, 'sold_by')) || text(findKey(page.product_results, 'sold_by'));
  const shipsFrom = text(findKey(page.purchase_options, 'ships_from')) || text(findKey(page.product_results, 'ships_from'));
  const bsr = (pd.best_sellers_rank || []).map(b => String(b.text || '').replace(/\s*\(See Top.*?\)\s*/i, '').trim()).filter(Boolean);
  const variants = (pr.variants || []).map(g => `${g.title}: ${(g.items || []).length}`);
  const insights = page.reviews_information?.summary?.insights || [];
  const themes = insights.map(t => ({
    theme: String(t.title || '').trim(),
    sentiment: t.sentiment || '',
    positive: t.mentions?.positive ?? null,
    negative: t.mentions?.negative ?? null,
    total: t.mentions?.total ?? null,
    summary: String(t.summary || '').trim(), // Amazon's own one-line summary of what customers say about this theme
  })).filter(t => t.theme && t.total !== null);
  // Star breakdown (% of ratings per star), when the page shows it
  const stars = page.reviews_information?.summary?.customer_reviews;
  const lowStarPct = stars && typeof stars === 'object' && ('1 star' in stars || '2 star' in stars)
    ? (Number(stars['1 star'] || 0) + Number(stars['2 star'] || 0)) : null;
  const brandKey = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return {
    json: {
      ...base,
      lookup_status: 'ok',
      lookup_note: themes.length ? '' : 'no review summary on this product page',
      real_brand: realBrand || NF,
      brand_guess_correct: realBrand && p.brand_guess ? (brandKey(realBrand).startsWith(brandKey(p.brand_guess)) || brandKey(p.brand_guess).startsWith(brandKey(realBrand)) ? 'yes' : 'no') : 'unknown',
      sold_by: soldBy || NF,
      ships_from: shipsFrom || NF,
      fulfilled_by_amazon: shipsFrom ? (/amazon/i.test(shipsFrom) ? 'yes' : 'no') : NF,
      bsr_category: bsr.length ? bsr[bsr.length - 1] : NF,
      bsr_all: bsr.length ? bsr.join(' | ') : NF,
      variations: variants.length ? variants.join(', ') : 'none listed',
      bought_last_month_page: pr.bought_last_month || NF,
      review_summary: page.reviews_information?.summary?.text || NF,
      one_two_star_pct: lowStarPct === null ? NF : lowStarPct,
      themes,
    },
  };
});

// One Products-tab row per inspected product; review themes written out as text
return $('Extract Products').all().map(i => {
  const { themes, ...p } = i.json;
  return {
    json: {
      ...p,
      review_themes: (themes || []).map(t => `${t.theme}: ${t.positive} positive / ${t.negative} negative of ${t.total} mentions${t.summary ? ` (Amazon: "${t.summary}")` : ''}`).join(' | ') || 'none',
    },
  };
});

// Judge each competitor as an ad target. Rules (published practice, m19's ASIN-targeting guide):
// target competitors priced ABOVE you, rated LOWER than you (or under 4.0 stars), with FEWER reviews than you,
// plus a heavy 1-2 star share when the product page shows it. Code writes every word; no AI.
const plan = $('Plan Run').first().json;
const rank = $('Rank Competitors').first().json;
const NF = 'not found';
const CUR = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' }[plan.marketplace] || '';
const money = v => (typeof v === 'number' ? `${CUR}${v.toFixed(2)}` : 'n/a');
const int = v => (typeof v === 'number' ? Math.round(v).toLocaleString('en-US') : 'n/a');
const numOrNull = v => (v === '' || v === null || v === undefined || v === NF || !Number.isFinite(Number(v)) ? null : Number(v));

// Fresh lookups from this run (if any ran)
const fresh = {};
try {
  if ($('Extract Products').isExecuted) for (const i of $('Extract Products').all()) fresh[i.json.asin] = i.json;
} catch (e) { /* no lookups were needed */ }

// What we compare against: your product when entered, else the market median
const you = plan.you;
const m = rank.market;
const basis = {
  price: you.price ?? m.price,
  rating: you.rating,             // no "market" rating rule: under 4.0 stars is the fallback
  reviews: you.reviews,
  label: [you.price !== null ? 'your price' : `market median price (${m.based_on})`,
    you.rating !== null ? 'your rating' : 'the 4.0-star line',
    you.reviews !== null ? 'your review count' : 'the 1,000-review line'].join(', '),
};

const rows = rank.listed.map(c => {
  const f = fresh[c.competitor_asin];
  const r = rank.reused[c.competitor_asin];
  const facts = f || r || null;
  const source = f ? (f.lookup_status === 'ok' ? 'product page (looked up now)' : `lookup failed: ${f.lookup_note}`)
    : r ? `product page (reused, looked up within 24 h, ${r.asin})` : 'search page only';
  const ok = facts && facts.lookup_status === 'ok';
  const lowStar = ok ? numOrNull(facts.one_two_star_pct) : null;

  const checks = [];
  if (typeof c.price === 'number' && typeof basis.price === 'number' && c.price >= basis.price * 1.05)
    checks.push(`priced above ${you.price !== null ? 'you' : 'the market median'} (${money(c.price)} vs ${money(basis.price)})`);
  if (typeof c.rating === 'number') {
    // 0.1 star is display rounding, not a real gap: at least 0.2 lower counts
    if (you.rating !== null && c.rating <= you.rating - 0.2 + 1e-9) checks.push(`rated lower than you (${c.rating.toFixed(1)} vs ${you.rating.toFixed(1)} stars)`);
    else if (you.rating === null && c.rating < 4.0) checks.push(`rated under 4.0 (${c.rating.toFixed(1)} stars)`);
  }
  if (you.reviews !== null && c.reviews < you.reviews) checks.push(`fewer reviews than you (${int(c.reviews)} vs ${int(you.reviews)})`);
  else if (you.reviews === null && c.reviews < 1000) checks.push(`under 1,000 reviews (${int(c.reviews)})`);
  if (lowStar !== null && lowStar >= 15) checks.push(`${lowStar}% of ratings are 1-2 stars`);

  const n = checks.length;
  const priority = (c.relevance >= 50 && n >= 2) ? 'High'
    : ((c.relevance >= 50 && n === 1) || (c.relevance >= 30 && n >= 2)) ? 'Medium' : 'Low';
  const sales = c.has_sales ? `${int(c.units_floor)}+ bought last month (badge floor)` : 'no sales badge';
  const reason = `Ranks on ${c.coverage} keywords (best #${c.best_position}), ${sales}. `
    + (n ? `Weak spots: ${checks.join('; ')}.` : 'No weak spot found against ' + (you.price !== null || you.rating !== null || you.reviews !== null ? 'your product' : 'the market') + ': an ad here competes with a stronger offer.');

  return {
    rank: c.rank,
    ad_priority: priority,
    relevance: c.relevance,
    competitor_asin: c.competitor_asin,
    other_asins: c.asins.filter(a => a !== c.competitor_asin).join(', '),
    brand: ok && facts.real_brand && facts.real_brand !== NF ? facts.real_brand : (c.brand ?? 'unknown'),
    brand_source: ok && facts.real_brand && facts.real_brand !== NF ? 'product page' : 'guessed from title',
    title: c.title,
    keywords_ranked_on: c.keywords_ranked_on,
    coverage: c.coverage,
    best_position: c.best_position,
    units_floor: c.has_sales ? c.units_floor : NF,
    page_sales_share_pct: c.page_sales_share_pct,
    price: c.price,
    rating: c.rating ?? NF,
    reviews: c.reviews,
    newcomer: c.newcomer ? 'yes' : 'no',
    weak_spots: checks.join(' | ') || 'none',
    weak_spot_count: n,
    compared_with: basis.label,
    reason,
    relevance_breakdown: c.relevance_breakdown,
    bsr: ok ? facts.bsr_category : NF,
    sold_by: ok ? facts.sold_by : NF,
    ships_from: ok ? facts.ships_from : NF,
    one_two_star_pct: lowStar === null ? NF : lowStar,
    facts_source: source,
  };
});

return [{ json: { rows } }];

// One Targets-tab row per competitor (top 25), keyed by run so re-runs never overwrite older lists
const plan = $('Plan Run').first().json;
const run_id = `i4|${plan.marketplace}|${plan.batch_id}`;
return $('Judge Targets').first().json.rows.map(r => ({
  json: { row_id: `${run_id}|${r.rank}`, run_id, checked_at: plan.batch_id, marketplace: plan.marketplace, keywords: plan.keywords.join(' | '), ...r },
}));

// Autopilot step 7: one report. A row for the Autopilot Runs tab, the text for the form, and the email (subject + HTML).
// Every number is copied from the earlier steps; nothing is recalculated or written by AI here.
const p = $('Plan Ideas').first().json;
const ideas = $('Collect Ideas').first().json;
const s = $('Plan Screen').first().json;
const w = $('Plan Run').first().json;
const core = $('Toolkit Core').first().json;
const rows = $('Judge Targets').first().json.rows;
const CUR = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' }[p.marketplace] || '';
const money = v => (typeof v === 'number' ? `${CUR}${v.toFixed(2)}` : 'n/a');
const int = v => (typeof v === 'number' ? Math.round(v).toLocaleString('en-US') : 'n/a');
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const run_id = `i4|${p.marketplace}|${p.batch_id}`;

let fresh = 0, failed = 0;
try { if ($('Extract Products').isExecuted) { const ex = $('Extract Products').all().map(i => i.json); fresh = ex.length; failed = ex.filter(e => e.lookup_status !== 'ok').length; } } catch (e) { /* no lookups */ }
const pagesSearched = s.pages.filter(x => !x.reuse).length;
const used = 1 + pagesSearched + fresh;
const markets = [...(core.markets || [])].sort((a, b) => a.rank - b.rank);
const win = markets.find(m => m.market === w.winner);
const failedKw = (core.keywords || []).filter(k => k.status !== 'ok').map(k => `${k.keyword} (${k.note || k.status})`);
const order = { High: 0, Medium: 1, Low: 2 };
const top = rows.filter(r => r.ad_priority !== 'Low').sort((a, b) => order[a.ad_priority] - order[b.ad_priority] || a.rank - b.rank).slice(0, 5);
const complements = ideas.rows.filter(r => r.group === 'nearby market').slice(0, 5).map(r => r.idea);
const notes = [...s.notes];
if (failedKw.length) notes.push(`Could not analyze: ${failedKw.join('; ')}`);
if (failed) notes.push(`${failed} product lookup(s) failed; those targets use search-page facts only`);
